#include <stdlib.h>#include <stdio.h>#include <string.h>#include "mesh.h"#include "256.h"void FileSeek ( short theFileRef, long thePos );void FileRead ( void *theDest, long theLenght, short theMeshFileRef );void FileWrite ( void *theDest, long theLenght, short theMeshFileRef );void textureStats (Str255 thePlugName, _256Header *theTextureHeader);void textureStats(Str255 thePlugName, struct _256Header *theTextureHeader){//----------------------------------vars--------------------------------------------------	short		thePlugFileRef;	OSErr		theError;	FSSpec		thePlugFSSpec;	int i;	struct sectionInfoEntry *sectionInfo;//----------------------------------------------------------------------------------------	// plug	theError = FSMakeFSSpec (0L, 0L, thePlugName, &thePlugFSSpec);	if ( theError != noErr )		return;	theError = FSpOpenDF ( &thePlugFSSpec, fsCurPerm, &thePlugFileRef );	if ( theError != noErr )		return;	FileRead ( theTextureHeader, sizeof( _256Header ), thePlugFileRef );	theTextureHeader->sectionInfoOffset += sizeof(struct _256Header);			// add header length to offset	theTextureHeader->paletteOffset += sizeof(struct _256Header);				// ditto	theTextureHeader->colorMapOffset += sizeof(struct _256Header);	sectionInfo = (struct sectionInfoEntry *) NewPtr ( theTextureHeader->sections * sizeof(sectionInfoEntry) );	FileSeek ( thePlugFileRef, theTextureHeader->sectionInfoOffset );	FileRead (sectionInfo, sizeof(struct sectionInfoEntry) * theTextureHeader->sections, thePlugFileRef );	FSClose ( thePlugFileRef );	for( i = 0; i < theTextureHeader->sections; i++ )		sectionInfo[i].offset += (sizeof(struct _256Header) + sizeof(struct textureHeader));			DisposePtr ( (char *) sectionInfo );}